function round(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function text(s,x,y,size=16,color='#216a6c',align='center'){ctx.font=`bold ${size}px Arial`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(s,x,y);}
function circle(x,y,r,c){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=c;ctx.fill();}
function palm(x,y){ctx.save();ctx.translate(x,y);ctx.strokeStyle='#c28d58';ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(0,5);ctx.quadraticCurveTo(12,-20,0,-44);ctx.stroke();for(let a=0;a<6;a++){ctx.save();ctx.translate(0,-45);ctx.rotate(a*Math.PI/3);ctx.fillStyle=a%2?'#39876b':'#4eaa77';ctx.beginPath();ctx.ellipse(20,0,33,9,.3,0,Math.PI*2);ctx.fill();ctx.restore();}ctx.restore();}
