function drawEffect(e){const t=e.t;ctx.save();if(e.kind==='dog'){const f=Math.min(1,e.t*4),x=e.from.x+(e.x-e.from.x)*f,y=e.from.y+(e.y-e.from.y)*f;const im=images.dog;ctx.save();ctx.translate(x-10,y-8-Math.sin(f*Math.PI)*35);ctx.rotate(-.35);if(im.complete)ctx.drawImage(im,-30,-40,55,60);ctx.restore();text('ГАВ! ЦАП!',x,y-80,17,'#fff6c6');ctx.strokeStyle='#fff9d4';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.moveTo(e.x+Math.cos(a)*22,e.y-15+Math.sin(a)*22);ctx.lineTo(e.x+Math.cos(a)*32,e.y-15+Math.sin(a)*32);}ctx.stroke();}else if(e.kind==='bucket'){const y=e.y-90+Math.min(1,t*3)*60;ctx.translate(e.x,y);ctx.rotate(Math.sin(t*10)*.2);round(-18,-20,36,30,5,'#88acb8','#ecffff');}else if(e.kind==='seal'){const f=Math.min(1,t*2),from=e.from||{x:e.x-80,y:e.y};const x=from.x+(e.x-from.x)*f,y=from.y+(e.y-from.y)*f-Math.sin(f*Math.PI)*100;ctx.fillStyle='#657e85';ctx.beginPath();ctx.ellipse(x,y-16,27,16,-.4,0,Math.PI*2);ctx.fill();circle(x+20,y-32,15,'#8ba8aa');circle(x+25,y-36,2,'#173f46');ctx.fillStyle='#53727a';ctx.beginPath();ctx.moveTo(x-16,y-8);ctx.lineTo(x-35,y+10);ctx.lineTo(x-22,y-16);ctx.fill();text('ЦАП!',x,y-55,16,'#fffbd8');}else if(e.kind==='puddle'){text('СКОЛЬЗКО!',e.x,e.y-85-t*12,13,'#f8fff0');}else if(e.kind==='spring'){text('ВЖУХ!',e.x,e.y-80-t*20,18,'#fff8cc');}for(let i=0;i<12;i++){const a=i*2.4,r=t*42;circle(e.x+Math.cos(a)*r,e.y+Math.sin(a)*r*.5-t*15,Math.max(1,5-t*2),'#e5ffff');}ctx.restore();}
// Open U-shaped waterslide mesh. Each face is built in XYZ, projected and shaded.
function drawSlideMesh(s){const faces=[],N=56,M=10,R=19;const cross=(t,a)=>{const u=1-t;const x=u*u*u*s.a.x+3*u*u*t*s.c.x+3*u*t*t*s.c.x+t*t*t*s.b.x;const y=u*u*u*s.a.y+3*u*u*t*s.c.y+3*u*t*t*(s.c.y+80)+t*t*t*s.b.y;const z=s.height*(u*u*u+3*u*u*t*.45);const dx=3*u*u*(s.c.x-s.a.x)+3*t*t*(s.b.x-s.c.x),dy=3*u*u*(s.c.y-s.a.y)+6*u*t*80+3*t*t*(s.b.y-s.c.y-80),l=Math.hypot(dx,dy)||1;return{x:x-dy/l*R*Math.sin(a),y:y+dx/l*R*Math.sin(a),z:z+R*(1-Math.cos(a))};};const project=p=>[p.x,p.y-p.z];for(let i=0;i<N;i++)for(let j=0;j<M;j++){const a=-Math.PI*.43+j/M*Math.PI*.86,b=-Math.PI*.43+(j+1)/M*Math.PI*.86,t=i/N,v=(i+1)/N;const pts=[cross(t,a),cross(v,a),cross(v,b),cross(t,b)];const light=.72+.28*Math.cos(a-.7);faces.push({pts,depth:pts.reduce((v,p)=>v+p.y,0)/4,j,light});}faces.sort((a,b)=>a.depth-b.depth);for(const f of faces){ctx.beginPath();f.pts.forEach((p,i)=>{const v=project(p);i?ctx.lineTo(...v):ctx.moveTo(...v);});ctx.closePath();if(f.j===0||f.j===M-1)ctx.fillStyle='#fff0cc';else if(f.j>=4&&f.j<=5)ctx.fillStyle='#a1e6ec';else{const hex=s.color.slice(1);ctx.fillStyle='rgb('+[0,2,4].map(i=>Math.round(parseInt(hex.slice(i,i+2),16)*f.light)).join(',')+')';}ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=.7;ctx.stroke();}for(const a of [-Math.PI*.43,Math.PI*.43]){ctx.beginPath();for(let i=0;i<=N;i++){const p=project(cross(i/N,a));i?ctx.lineTo(...p):ctx.moveTo(...p);}ctx.strokeStyle='#fff5dd';ctx.lineWidth=4;ctx.stroke();}}

