function advancePursuer(e,dt){if(!e.route&&slide){const base=stairBase(slides[slide.i]);if(Math.hypot(e.x-base.x,e.y-base.y)<38){e.route={i:slide.i,phase:'climb',t:0};e.z=0;}else{chase(e,dt,base);return;}}if(!e.route){chase(e,dt,player.hide?(e.lastSeen||{x:1000,y:100}):player);if(!player.hide)e.lastSeen={x:player.x,y:player.y};return;}const q=e.route,s=slides[q.i];e.moving=true;e.step=(e.step||0)+dt*9;if(q.phase==='climb'){q.t=Math.min(1,q.t+dt*(e.id==='slippy'?.47:.36));const b=stairBase(s),a=stairTop(s);e.x=b.x+(a.x-b.x)*q.t;e.y=b.y+(a.y-b.y)*q.t;e.z=s.height*q.t;e.dir='back';if(q.t===1){q.phase='platform';q.t=0;}}else if(q.phase==='platform'){q.t=Math.min(1,q.t+dt*1.15);const a=stairTop(s);e.x=a.x+(s.a.x-a.x)*q.t;e.y=a.y+(s.a.y-a.y)*q.t;e.z=s.height;e.dir='side';if(q.t===1){q.phase='ride';q.t=0;}}else{q.t=Math.min(1,q.t+dt*(e.id==='slippy'?.108:.098));const t=q.t,u=1-t;e.x=u*u*u*s.a.x+3*u*u*t*s.c.x+3*u*t*t*s.c.x+t*t*t*s.b.x;e.y=u*u*u*s.a.y+3*u*u*t*s.c.y+3*u*t*t*(s.c.y+80)+t*t*t*s.b.y;e.z=s.height*(u*u*u+3*u*u*t*.45);if(t===1){e.route=null;e.z=0;snapToRoad(e);e.stun=.6;}}}
