function drawPlayerRider(x,y){if(riderArt.complete&&riderArt.naturalWidth){const cw=riderArt.naturalWidth/3,w=205,h=w*riderArt.naturalHeight/cw;ctx.save();ctx.translate(x,y);ctx.rotate((slide?.steer||0)*.15+Math.sin(elapsed*3.6)*.025);ctx.scale(1+Math.sin(elapsed*4)*.012,1+Math.cos(elapsed*4)*.012);ctx.drawImage(riderArt,cw*hero,0,cw,riderArt.naturalHeight,-w/2,-h+27,w,h);ctx.restore();}else seatedHero(x,y,1.13);}

function buildWalkMask(z){if(walkMasks[z])return;const im=sceneImages[z];if(!im?.complete||!im.naturalWidth)return;const c=document.createElement('canvas');c.width=1200;c.height=720;const g=c.getContext('2d',{willReadFrequently:true});g.drawImage(im,0,0,1200,720);const pixels=g.getImageData(0,0,1200,720).data,mask=new Uint8Array(MASK_W*MASK_H);function floor(x,y){const k=(Math.max(0,Math.min(719,y))*1200+Math.max(0,Math.min(1199,x)))*4,r=pixels[k],v=pixels[k+1],b=pixels[k+2];return r>85&&v>60&&b>30&&r>v*1.025&&v>b*1.045&&r<v*1.8;}
for(let y=0;y<MASK_H;y++)for(let x=0;x<MASK_W;x++){const px=x*5+2,py=y*5+2;let votes=0;for(const dx of [-3,0,3])for(const dy of [-3,0,3])votes+=floor(px+dx,py+dy);mask[y*MASK_W+x]=votes>=4?1:0;}
// Close tiny texture holes; planted green islands and water remain blocked.
let smooth=mask.slice();for(let y=1;y<MASK_H-1;y++)for(let x=1;x<MASK_W-1;x++){let n=0;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)n+=mask[(y+dy)*MASK_W+x+dx];smooth[y*MASK_W+x]=n>=4?1:0;}for(const s of zones[z].slides){const b=stairBase(s);for(let y=Math.floor((b.y-16)/5);y<=Math.ceil((b.y+16)/5);y++)for(let x=Math.floor((b.x-16)/5);x<=Math.ceil((b.x+16)/5);x++)if(x>=0&&x<MASK_W&&y>=0&&y<MASK_H)smooth[y*MASK_W+x]=1;}// Keep only connected footpaths, expanding by one five-pixel cell for shadows and tile seams.
const expanded=smooth.slice();for(let y=1;y<MASK_H-1;y++)for(let x=1;x<MASK_W-1;x++)if(smooth[y*MASK_W+x])for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])expanded[(y+dy)*MASK_W+x+dx]=1;
for(let y=0;y<MASK_H;y++)for(let x=0;x<MASK_W;x++){const px=x*5+2,py=y*5+2;if(px<45||px>1165||py<75||py>675||wetShapes[z].some(p=>inPoly(px,py,p))||(z===1&&riverBlocked(px,py)))expanded[y*MASK_W+x]=0;}
const seen=new Uint8Array(expanded.length);let largest=[];for(let i=0;i<expanded.length;i++){if(!expanded[i]||seen[i])continue;const cells=[i];seen[i]=1;for(let j=0;j<cells.length;j++){const k=cells[j],x=k%MASK_W,y=Math.floor(k/MASK_W);for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy;if(nx<0||nx>=MASK_W||ny<0||ny>=MASK_H)continue;const n=ny*MASK_W+nx;if(expanded[n]&&!seen[n]){seen[n]=1;cells.push(n);}}}if(cells.length>largest.length)largest=cells;}const connected=new Uint8Array(expanded.length);for(const k of largest)connected[k]=1;walkMasks[z]=connected;}
function onRoad(x,y){buildWalkMask(zone);const m=walkMasks[zone];if(!m)return true;const ix=Math.floor(x/5),iy=Math.floor(y/5);return ix>=0&&ix<MASK_W&&iy>=0&&iy<MASK_H&&!!m[iy*MASK_W+ix];}
function snapToRoad(e){if(!blocked(e.x,e.y))return;let best=null,d=Infinity;for(let y=80;y<675;y+=8)for(let x=48;x<1165;x+=8){const q=(x-e.x)**2+(y-e.y)**2;if(q<d&&!blocked(x,y)){best={x,y};d=q;}}if(best){e.x=best.x;e.y=best.y;}}
function artCell(im,col,row,cols,rows,x,y,w,h,alpha=1){if(!im.complete||!im.naturalWidth)return false;ctx.save();ctx.globalAlpha*=alpha;const cw=im.naturalWidth/cols,ch=im.naturalHeight/rows;ctx.drawImage(im,cw*col,ch*row,cw,ch,x,y,w,h);ctx.restore();return true;}
function drawTrap(t){const kinds=['foam','puddle','bucket','seal','spring'],i=kinds.indexOf(t.kind||'foam'),pulse=Math.sin(motionTime*3+t.x)*1.3,w=[89,96,88,95,87][i],h=[74,58,128,94,105][i];ctx.save();ctx.translate(t.x,t.y+pulse);const arm=Math.min(1,(elapsed-(t.placedAt||0))/.35);ctx.scale(.6+.4*arm,.6+.4*arm);ctx.rotate(i===4?Math.sin(motionTime*4)*.025:0);artCell(trapArt,i,0,5,2,-w/2,-h+17,w,h);ctx.restore();}
function drawTriggeredTrap(e){const i=['foam','puddle','bucket','seal','spring'].indexOf(e.kind);if(i<0)return;const f=e.t/e.duration,size=100+Math.sin(Math.min(1,f*2)*Math.PI)*35;let x=e.x,y=e.y-(e.z||0);if(e.kind==='seal'&&e.from){const p=Math.min(1,e.t*2);x=e.from.x+(e.x-e.from.x)*p;y=e.from.y+(e.y-e.from.y)*p-Math.sin(p*Math.PI)*75;}ctx.save();ctx.translate(x,y);ctx.rotate(e.kind==='spring'?Math.sin(e.t*10)*.07:0);artCell(trapArt,i,1,5,2,-size/2,-size+30,size,size,Math.min(1,(1-f)*3));ctx.restore();waterSprite(0,e.t*8,x-70,y-45,140,90,Math.max(0,1-f));}
function waterClip(z){ctx.beginPath();for(const shape of wetShapes[z]){shape.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();}ctx.clip();}
function drawLiveMap(scene){const time=motionTime;ctx.save();waterClip(zone);const ratioX=scene.naturalWidth/1200,ratioY=scene.naturalHeight/720;ctx.globalAlpha=.48;for(let y=80;y<675;y+=5){const offset=Math.sin(y*.047+time*2.7)*3.2,sy=Math.max(0,Math.min(714,y+Math.sin(y*.029-time*1.8)*3));ctx.drawImage(scene,0,sy*ratioY,scene.naturalWidth,5*ratioY,offset,y,1200,5);}ctx.globalAlpha=1;for(let i=0;i<12;i++){const shape=wetShapes[zone][i%wetShapes[zone].length],cx=shape.reduce((v,p)=>v+p[0],0)/shape.length,cy=shape.reduce((v,p)=>v+p[1],0)/shape.length,x=cx+Math.sin(i*6.1+time*.2)*95,y=cy+Math.cos(i*9.3+time*.25)*60;waterSprite(1,time*4+i,x-45,y-25,90,50,.32);}ctx.restore();
// Light leaves sway independently of the water; no global map wobble.
for(let i=0;i<5;i++){const x=[70,1100,150,1030,700][i],y=[320,140,565,560,95][i],sx=x*ratioX,sy=y*ratioY;ctx.save();ctx.globalAlpha=.18;ctx.beginPath();ctx.ellipse(x,y,23,15,0,0,Math.PI*2);ctx.clip();ctx.drawImage(scene,sx-28*ratioX,sy-21*ratioY,56*ratioX,42*ratioY,x-28+Math.sin(time*1.3+i)*2,y-21,56,42);ctx.restore();}
}
function rideWaterClip(){ctx.beginPath();ctx.moveTo(0,720);ctx.lineTo(1200,720);ctx.lineTo(1150,575);ctx.lineTo(930,490);ctx.lineTo(740,425);ctx.lineTo(730,340);ctx.lineTo(790,268);ctx.lineTo(680,335);ctx.lineTo(615,410);ctx.lineTo(365,472);ctx.lineTo(70,565);ctx.closePath();ctx.clip();}
function drawFlowingRideWater(){if(!rideArt.complete||!rideArt.naturalWidth)return;const t=motionTime,rx=rideArt.naturalWidth/1200,ry=rideArt.naturalHeight/720;ctx.save();rideWaterClip();ctx.globalAlpha=.37;for(let y=280;y<720;y+=5){const depth=(y-260)/460,shift=4+depth*9,sy=y+Math.sin(y*.043-t*4)*shift,dx=Math.sin(y*.025+t*3)*depth*8;ctx.drawImage(rideArt,0,Math.max(0,Math.min(714,sy))*ry,rideArt.naturalWidth,5*ry,dx,y,1200,5);}ctx.globalAlpha=1;for(let i=0;i<10;i++){const q=(i/10+t*.28)%1,x=600+(1-q)*180+Math.sin(i*3.3)*q*330,y=270+q*q*480,w=30+q*160;waterSprite(1,t*6+i,x-w/2,y-w*.2,w,w*.5,.22+q*.25);}ctx.restore();}
function drawRideWake(x,y){const frame=Math.floor(motionTime*10)%4;ctx.save();ctx.translate(x,y);ctx.rotate((slide?.steer||0)*.17);waterSprite(0,motionTime*6,-145,-45,290,175,.88);ctx.restore();}

function drawFloatingRing(x,y,scale){if(!trapArt.complete||!trapArt.naturalWidth)return;const cw=trapArt.naturalWidth/5,ch=trapArt.naturalHeight/2;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(motionTime*4+x)*.08);ctx.drawImage(trapArt,cw*4,0,cw,ch*.47,-42*scale,-35*scale,84*scale,55*scale);ctx.restore();}
function drawSlideStream(s){for(let i=0;i<5;i++){const t=(motionTime*.22+i/5)%1,u=1-t,x=u*u*u*s.a.x+3*u*u*t*s.c.x+3*u*t*t*s.c.x+t*t*t*s.b.x,y=u*u*u*s.a.y+3*u*u*t*s.c.y+3*u*t*t*(s.c.y+80)+t*t*t*s.b.y,z=s.height*(u*u*u+3*u*u*t*.45);waterSprite(1,motionTime*5+i,x-15,y-z-8,30,18,.6);}}
document.querySelectorAll('[data-trap]').forEach((b,i)=>{b.innerHTML='<span class="trap-icon" style="background-position:'+i*25+'% 0%"></span><span>'+['Пена','Лужа','Ведро','Котик','Пружина'][i]+'</span>';});

function waterSprite(row,phase,x,y,w,h,alpha){const i=Math.floor(phase)%4,f=phase%1;artCell(waterArt,i,row,4,2,x,y,w,h,alpha*(1-f));artCell(waterArt,(i+1)%4,row,4,2,x,y,w,h,alpha*f);}
